<?php
declare(strict_types=1);require_once __DIR__.'/config/database.php';require_once __DIR__.'/includes/auth.php';requireAdmin();$errors=[];$notice='';$edit=null;if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){if(!verifyCsrfToken())$errors[]='Permintaan tidak valid.';else{$a=$_POST['action']??'';$id=(int)($_POST['klasifikasi_id']??0);if($a==='delete'&&$id){$s=$pdo->prepare('SELECT COUNT(*) FROM arsip WHERE klasifikasi_id=:id');$s->execute(['id'=>$id]);if((int)$s->fetchColumn())$errors[]='Klasifikasi arsip masih digunakan arsip dan tidak dapat dihapus.';else{$pdo->prepare('DELETE FROM klasifikasi_arsip WHERE klasifikasi_id=:id')->execute(['id'=>$id]);logActivity($pdo,(int)$_SESSION['user_id'],'DELETE');$notice='Klasifikasi arsip berhasil dihapus.';}}if(in_array($a,['create','update'],true)){$v=['kode_klasifikasi'=>trim((string)($_POST['kode_klasifikasi']??'')),'nama_klasifikasi'=>trim((string)($_POST['nama_klasifikasi']??'')),'deskripsi'=>trim((string)($_POST['deskripsi']??''))?:null];if($v['kode_klasifikasi']===''||$v['nama_klasifikasi']==='')$errors[]='Kode dan nama klasifikasi wajib diisi.';$s=$pdo->prepare('SELECT klasifikasi_id FROM klasifikasi_arsip WHERE kode_klasifikasi=:kode AND klasifikasi_id!=:id');$s->execute(['kode'=>$v['kode_klasifikasi'],'id'=>$id]);if($s->fetch())$errors[]='Kode klasifikasi sudah digunakan.';if(!$errors&&$a==='create'){$pdo->prepare('INSERT INTO klasifikasi_arsip(kode_klasifikasi,nama_klasifikasi,deskripsi) VALUES(:kode_klasifikasi,:nama_klasifikasi,:deskripsi)')->execute($v);logActivity($pdo,(int)$_SESSION['user_id'],'CREATE');$notice='Klasifikasi arsip berhasil ditambahkan.';}if(!$errors&&$a==='update'&&$id){$pdo->prepare('UPDATE klasifikasi_arsip SET kode_klasifikasi=:kode_klasifikasi,nama_klasifikasi=:nama_klasifikasi,deskripsi=:deskripsi WHERE klasifikasi_id=:id')->execute($v+['id'=>$id]);logActivity($pdo,(int)$_SESSION['user_id'],'UPDATE');$notice='Klasifikasi arsip berhasil diperbarui.';}}}}if(isset($_GET['edit'])){$s=$pdo->prepare('SELECT * FROM klasifikasi_arsip WHERE klasifikasi_id=:id');$s->execute(['id'=>(int)$_GET['edit']]);$edit=$s->fetch()?:null;}$q=trim((string)($_GET['q']??''));$s=$pdo->prepare('SELECT k.*,(SELECT COUNT(*) FROM arsip a WHERE a.klasifikasi_id=k.klasifikasi_id) archive_count FROM klasifikasi_arsip k WHERE k.kode_klasifikasi LIKE :q1 OR k.nama_klasifikasi LIKE :q2 ORDER BY k.kode_klasifikasi');$s->execute(['q1'=>"%$q%",'q2'=>"%$q%"]);$items=$s->fetchAll();?>
