rm method="post" class="admin-form"><input type="hidden" name="csrf_token" value="<?=e(csrfToken())?>"><input type="hidden" name="action" value="<?=$edit?'update':'create'?>"><?php if($edit):?><input type="hidden" name="klasifikasi_id" value="<?=(int)$edit['klasifikasi_id']?>"><?php endif;?><label>Kode Klasifikasi<input name="kode_klasifikasi" required maxlength="50" value="<?=e($edit['kode_klasifikasi']??'')?>"></label><label>Nama Klasifikasi<input name="nama_klasifikasi" required maxlength="150" value="<?=e($edit['nama_klasifikasi']??'')?>"></label><label>Deskripsi<textarea name="deskripsi"><?=e($edit['deskripsi']??'')?></textarea></label><div><button class="primary-button">Simpan</button></div></form></section><section class="panel user-list"><h2>Daftar Klasifikasi Arsip</h2><form class="filter-form"><input name="q" value="<?=e($q)?>" placeholder="Cari kode atau nama klasifikasi"><button>Cari</button></form><div class="table-wrap"><table><thead><tr><th>Kode</th><th>Nama</th><th>Arsip</th><th>Aksi</th></tr></thead><tbody><?php foreach($items as $x):?><tr><td><?=e($x['kode_klasifikasi'])?></td><td><?=e($x['nama_klasifikasi'])?></td><td><?=(int)$x['archive_count']?></td><td><a href="klasifikasi-arsip.php?edit=<?=(int)$x['klasifikasi_id']?>">Edit</a><form method="post" class="inline-form"><input type="hidden" name="csrf_token" value="<?=e(csrfToken())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="klasifikasi_id" value="<?=(int)$x['klasifikasi_id']?>"><button>Hapus</button></form></td></tr><?php endforeach;?></tbody></table></div></section></main></div></body></html>